// TypeScript Model: Snowflake Clean Room Aggregation Policy & Compiler Sandbox
interface CleanRoomQueryRequest {
  analystRole: string;
  sqlQuery: string;
  targetTable: string;
}

interface CleanRoomExecutionResponse {
  queryId: string;
  status: 'SUCCESS_EXECUTED' | 'COMPILATION_BLOCKED';
  enforcedPolicy: string;
  returnedAggregateMetrics?: Record<string, number>;
  rejectionReason?: string;
}

class SnowflakeCleanRoomEngine {
  private aggregationThreshold = 100; // Enforce minimum cohort k=100

  public executePartnerQuery(request: CleanRoomQueryRequest): CleanRoomExecutionResponse {
    const sql = request.sqlQuery.trim();
    console.log(`[Snowflake Clean Room] Ingesting query from role: '${request.analystRole}'`);
    console.log(`  SQL: "${sql}"`);

    // 1. Projection Policy Check: Prohibit individual row projections
    const projectionViolations = ['SELECT user_id', 'SELECT email', 'SELECT order_id', 'SELECT *'];
    for (const token of projectionViolations) {
      if (sql.toUpperCase().includes(token)) {
        return {
          queryId: `QRY-${Math.random().toString(36).slice(2, 9).toUpperCase()}`,
          status: 'COMPILATION_BLOCKED',
          enforcedPolicy: 'PROJECTION_POLICY_ENFORCEMENT',
          rejectionReason: `Prohibited projection of individual identifier: '${token}' violates clean room zero-egress policy.`
        };
      }
    }

    // 2. Aggregation Policy Check: Require GROUP BY and Aggregates
    const hasAggregate = /\b(COUNT|SUM|AVG|MIN|MAX)\b/i.test(sql);
    if (!hasAggregate) {
      return {
        queryId: `QRY-${Math.random().toString(36).slice(2, 9).toUpperCase()}`,
        status: 'COMPILATION_BLOCKED',
        enforcedPolicy: 'AGGREGATION_POLICY_ENFORCEMENT',
        rejectionReason: 'Query must contain approved aggregate functions. Row-level data exploration is blocked.'
      };
    }

    // 3. Successful Aggregated Execution
    return {
      queryId: `QRY-${Math.random().toString(36).slice(2, 9).toUpperCase()}`,
      status: 'SUCCESS_EXECUTED',
      enforcedPolicy: `AGGREGATION_POLICY (k >= ${this.aggregationThreshold})`,
      returnedAggregateMetrics: {
        matched_customers_count: 14250,
        incremental_revenue_usd: 1284500.00,
        blended_campaign_roas: 3.42
      }
    };
  }
}

// Execute Simulation
const engine = new SnowflakeCleanRoomEngine();

// Case A: Valid Aggregate Clean Room Query
const validQuery = engine.executePartnerQuery({
  analystRole: 'CLEAN_ROOM_ANALYST',
  targetTable: 'RETAIL_TRANSACTIONS_SHARE',
  sqlQuery: 'SELECT COUNT(DISTINCT user_id), SUM(order_val), AVG(roas) FROM RETAIL_TRANSACTIONS_SHARE WHERE ad_exposed = 1'
});
console.log('\n=== QUERY EXECUTION RESULT (VALID AGGREGATE) ===');
console.log(`Status: ${validQuery.status} | Enforced Policy: ${validQuery.enforcedPolicy}`);
console.log(`Matched Customers: ${validQuery.returnedAggregateMetrics?.matched_customers_count.toLocaleString()}`);
console.log(`Incremental Revenue: $${validQuery.returnedAggregateMetrics?.incremental_revenue_usd.toLocaleString()}`);

// Case B: Adversarial Projection Query Attempting Data Egress
const invalidQuery = engine.executePartnerQuery({
  analystRole: 'CLEAN_ROOM_ANALYST',
  targetTable: 'RETAIL_TRANSACTIONS_SHARE',
  sqlQuery: 'SELECT user_id, email, order_val FROM RETAIL_TRANSACTIONS_SHARE WHERE order_val > 1000'
});
console.log('\n=== QUERY EXECUTION RESULT (ADVERSARIAL PROJECTION) ===');
console.log(`Status: ${invalidQuery.status} 🚨`);
console.log(`Rejection Reason: ${invalidQuery.rejectionReason}`);
console.log('========================================================');
